#define NOMINMAX
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include "gi_bypass.h"
#include "gi_raw_cs.h" // generated by build.bat: g_gi_raw_cs_1, _pi, _2, _half

#include <atomic>
#include <mutex>
#include <set>
#include <unordered_map>

void logf(const char *fmt, ...);

namespace gi
{
	static constexpr uint64_t k_hash_temporal = 0xea12dd2b624b6962ull;
	static constexpr uint64_t k_hash_spatial  = 0x6e9ffce615b836daull;

	struct Variant { const char *name; const void *code; size_t size; };
	static const Variant k_variants[] = {
		{ "x1",   g_gi_raw_cs_1,    sizeof(g_gi_raw_cs_1) },
		{ "xPI",  g_gi_raw_cs_pi,   sizeof(g_gi_raw_cs_pi) },
		{ "x2",   g_gi_raw_cs_2,    sizeof(g_gi_raw_cs_2) },
		{ "x0.5", g_gi_raw_cs_half, sizeof(g_gi_raw_cs_half) },
	};
	static constexpr int k_variant_count = sizeof(k_variants) / sizeof(k_variants[0]);

	static std::atomic<bool> s_enabled{false};
	static std::atomic<int> s_scale{0};
	static std::atomic<bool> s_allowed{true};

	static std::mutex s_mtx;
	static std::set<uint64_t> s_temporal_pipes, s_spatial_pipes;
	static ID3D12PipelineState *s_pso[k_variant_count] = {};
	static ID3D12RootSignature *s_pso_rootsig = nullptr;

	struct ListState { int kind = 0; int spatial_count = 0; };
	static std::unordered_map<uint64_t, ListState> s_lists;

	bool enabled() { return s_enabled.load(); }
	void set_enabled(bool on) { s_enabled = on; }
	void set_allowed(bool allowed) { s_allowed = allowed; }
	void set_scale(int index) { if (index >= 0 && index < k_variant_count) s_scale = index; }
	void toggle()
	{
		const bool on = !s_enabled.load();
		s_enabled = on;
		std::lock_guard lock(s_mtx);
		logf("GI bypass: %s (scale %s, temporal pipes %zu, spatial pipes %zu, replacement %s)", on ? "ON" : "OFF",
			k_variants[s_scale.load()].name, s_temporal_pipes.size(), s_spatial_pipes.size(), s_pso[0] ? "ready" : "NOT created");
	}
	void next_scale()
	{
		const int s = (s_scale.load() + 1) % k_variant_count;
		s_scale = s;
		logf("GI bypass scale: %s", k_variants[s].name);
	}

	static void create_variants(ID3D12Device *device, ID3D12RootSignature *rs)
	{
		if (s_pso_rootsig == rs && s_pso[0]) return;
		for (auto &p : s_pso) { if (p) p->Release(); p = nullptr; }
		s_pso_rootsig = rs;
		for (int i = 0; i < k_variant_count; ++i)
		{
			D3D12_COMPUTE_PIPELINE_STATE_DESC d = {};
			d.pRootSignature = rs;
			d.CS = { k_variants[i].code, k_variants[i].size };
			const HRESULT hr = device->CreateComputePipelineState(&d, IID_PPV_ARGS(&s_pso[i]));
			if (FAILED(hr))
			{
				logf("GI bypass: creating replacement pipeline %s with the game's root signature failed 0x%08lx", k_variants[i].name, hr);
				s_pso[i] = nullptr;
			}
		}
		if (s_pso[0]) logf("GI bypass: replacement pipelines created (root signature %p)", rs);
	}

	void on_pipeline(ID3D12Device *device, ID3D12RootSignature *rs, uint64_t hash, uint64_t pipeline)
	{
		if (hash != k_hash_temporal && hash != k_hash_spatial) return;
		std::lock_guard lock(s_mtx);
		if (hash == k_hash_temporal) s_temporal_pipes.insert(pipeline);
		else
		{
			s_spatial_pipes.insert(pipeline);
			if (device && rs) create_variants(device, rs);
		}
	}

	void on_destroy_pipeline(uint64_t pipeline)
	{
		std::lock_guard lock(s_mtx);
		s_temporal_pipes.erase(pipeline);
		s_spatial_pipes.erase(pipeline);
	}

	void on_bind_compute(uint64_t list, uint64_t pipeline)
	{
		std::lock_guard lock(s_mtx);
		const int kind = s_temporal_pipes.count(pipeline) ? 1 : s_spatial_pipes.count(pipeline) ? 2 : 0;
		if (kind == 0)
		{
			auto it = s_lists.find(list);
			if (it != s_lists.end()) it->second.kind = 0;
			return;
		}
		s_lists[list].kind = kind;
	}

	void on_reset(uint64_t list)
	{
		std::lock_guard lock(s_mtx);
		s_lists.erase(list);
	}

	bool on_dispatch(uint64_t list, ID3D12GraphicsCommandList *native)
	{
		if (!s_enabled.load() || !s_allowed.load() || !native) return false;
		std::lock_guard lock(s_mtx);
		auto it = s_lists.find(list);
		if (it == s_lists.end() || it->second.kind == 0) return false;
		ListState &st = it->second;
		ID3D12PipelineState *pso = s_pso[s_scale.load()];
		if (!pso) return false; // replacement unavailable: leave the game's denoiser alone

		if (st.kind == 1) // temporal pass: start of the chain
		{
			st.spatial_count = 0;
			return true; // skip
		}
		// spatial pass
		++st.spatial_count;
		if (st.spatial_count == 1)
			return true; // skip pass #1 (it would overwrite the raw signal)
		if (st.spatial_count == 2)
		{
			native->SetPipelineState(pso); // pass #2 runs our shader with the game's bindings
			static bool logged = false;
			if (!logged) { logged = true; logf("GI bypass: first replacement dispatch recorded"); }
		}
		return false;
	}
}
